(function attachPlanImages() {
  var images = {
    "tax-saving": "images/plan-cards/card-savings.png",
    "life-wealth-fit-99-99": "images/plan-cards/card-protect.png",
    "health-working": "images/plan-cards/card-health.png",
    infinite: "images/plan-cards/card-rider.png",
    "legacy-fit-retire": "images/plan-cards/card-pension.png",
    "universal-life": "images/plan-cards/card-invest.png"
  };
  Object.keys(images).forEach(function (key) {
    var plan = window.PLANS_DETAIL[key];
    if (!plan || (plan.sections && plan.sections.length)) return;
    plan.image = images[key];
  });
})();
